'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=x=>x===null||x===undefined?'不适用':new Intl.NumberFormat('zh-CN').format(x);
const percent=x=>x===null||x===undefined?'不适用':(x*100).toFixed(2)+'%';
const pp=x=>x===null?'不适用':(x*100).toFixed(2)+' 个百分点';
const money=(x,c)=>number((x||0)/100)+' '+c;
let current=window.OLIST_CASE,candidate=null,checkedQuality=null,worker=null,activeChart='monthly',database=null,importRun=0;
function message(s,error=false){$('#global-message').textContent=s;$('#global-message').classList.toggle('error',error);$('#global-message').classList.toggle('hidden',!s);}
function download(name,text,mime='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:mime}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('olist-lens-v1',1);r.onupgradeneeded=()=>{const d=r.result;d.createObjectStore('snapshots',{keyPath:'id'});d.createObjectStore('settings');};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function getValue(store,key){return new Promise((resolve,reject)=>{const r=database.transaction(store).objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function getSnapshots(){return new Promise((resolve,reject)=>{const r=database.transaction('snapshots').objectStore('snapshots').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function saveSnapshot(data){return new Promise((resolve,reject)=>{const tx=database.transaction(['snapshots','settings'],'readwrite');if(data)tx.objectStore('snapshots').put(data);tx.objectStore('settings').put(data?data.id:null,'current');tx.oncomplete=resolve;tx.onabort=()=>reject(tx.error||Error('保存中断'));tx.onerror=()=>{};});}
const titles={overview:['经营诊断','从履约差异中，识别值得验证的运营机会。'],quality:['数据质量','看清输入范围、检查记录与独立复算证据。'],import:['导入新数据','完整快照先预览、再校验，通过后才切换。'],history:['版本记录','恢复本机快照，保留每次分析的数据范围与口径。'],methods:['方法与项目','明确指标边界，让每个结论都有可以复查的证据。']};
function panel(name){if(!titles[name])name='overview';$$('.panel').forEach(el=>el.classList.toggle('hidden',el.id!=='panel-'+name));$$('.nav-button').forEach(el=>{el.classList.toggle('active',el.dataset.panel===name);el.setAttribute('aria-current',el.dataset.panel===name?'page':'false');});$('#page-title').textContent=titles[name][0];$('#page-subtitle').textContent=titles[name][1];history.replaceState(null,'','#'+name);if(name==='history')renderHistory();}
$$('.nav-button').forEach(b=>b.addEventListener('click',()=>panel(b.dataset.panel)));
function findings(r){const m=r.metrics,late=r.association.find(x=>x.delivery_group==='late'),on=r.association.find(x=>x.delivery_group==='on_time'),top=r.states.slice(0,2);const sum=top.reduce((s,x)=>s+(x.late_orders||0),0);const lines=[];
 if(m.delivery_eligible)lines.push(`<b>履约问题需要结合规模定位。</b> ${number(m.delivery_eligible)} 笔履约日期有效的已交付订单中，${number(m.late_orders)} 笔延迟（${percent(m.late_rate)}）；${top.map(s=>esc(s.state)).join('、')} 合计贡献 ${percent(m.late_orders?sum/m.late_orders:null)} 的延迟订单。`);
 if(late&&on)lines.push(`<b>延迟与低评分存在观察性关联。</b> 延迟组低评分率为 ${percent(late.rate)}（n=${number(late.n)}），按时组为 ${percent(on.rate)}（n=${number(on.n)}），相差 ${pp(late.rate-on.rate)}。该差异不能直接解释为延迟导致的影响。`);
 else lines.push('<b>评价关联证据不足。</b> 需要同时具有有效履约日期与评分的按时、延迟订单，才可做分组对照。');
 if(r.stratified.orders)lines.push(`<b>优先验证高影响群体的履约改善。</b> 按月份 × 地区分层后，加权差异为 ${pp(r.stratified.weighted_difference)}，覆盖交叉样本的 ${percent(r.stratified.coverage)}；未控制全部混杂，建议小范围试点。`);
 else lines.push('<b>下一步先补齐证据。</b> 当前共同分层样本不足，先检查缺失覆盖与订单构成，避免据此承诺改善幅度。');return lines;
}
function render(){if(!current)return;const r=current,m=r.metrics;$('#dataset-name').textContent=r.manifest.dataset_name;$('#dataset-range').textContent=r.manifest.coverage_start+' 至 '+r.manifest.coverage_end;$('#dataset-status').textContent='数据'+r.quality.status+' · 复算'+r.verification.status;$('#dataset-id').textContent=r.id.slice(0,12);$('#findings').innerHTML=findings(r).map(s=>'<p>'+s+'</p>').join('');
 const cards=[['已交付订单数',number(m.delivered_orders),'全部状态订单 '+number(m.total_orders)+' 笔'],['商品金额 / '+esc(r.manifest.currency),number(m.amount_cents/100),'已交付订单，不含运费，非平台收入'],['延迟交付率',percent(m.late_rate),number(m.late_orders)+' / '+number(m.delivery_eligible)+' 笔有效订单'],['低评分订单占比',percent(m.low_rate),number(m.low_reviews)+' / '+number(m.review_eligible)+' 笔有效评分']];
 $('#metric-cards').innerHTML=cards.map(([a,b,c])=>`<article class="metric"><div class="metric-label">${a}</div><div class="metric-value">${esc(b)}</div><small>${esc(c)}</small></article>`).join('');
 const top=r.states[0];$('#action-notes').innerHTML=[['01','从规模与比率一起判断',top?`${top.state} 有 ${number(top.late_orders)} 笔延迟，延迟率 ${percent(top.late_rate)}。与高比率小样本地区分开评估。`:'先补充有效订单。'],['02','检查交付链路与订单构成','在重点地区继续核对卖家、品类与承诺时间，避免将构成差异直接归因为单一环节。'],['03','用试点验证真实改善','监控延迟率、低评分率及客服负担，结合对照和样本覆盖评估，记录未改善的结果。']].map(([n,t,p])=>`<div class="action-item"><span class="number">${n} / NEXT STEP</span><h3>${t}</h3><p>${esc(p)}</p></div>`).join('');
 $('#state-table').innerHTML=r.states.map(x=>`<tr><td>${esc(x.state)}</td><td>${number(x.delivered_orders)}</td><td>${number(x.delivery_eligible)}</td><td>${number(x.late_orders||0)}</td><td>${percent(x.late_rate)}</td><td>${percent(m.late_orders?(x.late_orders||0)/m.late_orders:null)}</td></tr>`).join('');
 renderChart(activeChart);renderQuality();
}
function svg(content,label){return `<svg class="chart-svg" viewBox="0 0 720 285" role="img" aria-label="${esc(label)}"><title>${esc(label)}</title>${content}</svg>`;}
function renderChart(name){activeChart=name;const r=current;$$('[data-chart]').forEach(b=>{const on=b.dataset.chart===name;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;});let body='';
 $('#chart').setAttribute('aria-labelledby','chart-tab-'+name);
 if(name==='monthly'){
  $('#chart-title').textContent='月度订单趋势';$('#chart-unit').textContent='已交付订单 / 单';const rows=r.monthly,max=Math.max(...rows.map(x=>x.delivered_orders),1),ymax=Math.ceil(max/5)*5;const monthN=s=>+s.slice(0,4)*12+(+s.slice(5,7)-1);const first=monthN(r.manifest.coverage_start),last=monthN(r.manifest.coverage_end),byMonth=new Map(rows.map(x=>[x.month,x]));const points=[];
  for(let n=first;n<=last&&n-first<1200;n++){const month=Math.floor(n/12)+'-'+String(n%12+1).padStart(2,'0');const row=byMonth.get(month);points.push({month,n:row?.delivered_orders||0});}
  const x=i=>58+i/Math.max(points.length-1,1)*632,y=v=>232-v/ymax*198;
  for(let i=0;i<=4;i++){const v=ymax*i/4;body+=`<line x1="58" y1="${y(v)}" x2="690" y2="${y(v)}" stroke="#e2e8dd"/><text x="48" y="${y(v)+4}" text-anchor="end">${number(Math.round(v))}</text>`;}
  body+=`<path d="${points.map((p,i)=>(i?'L':'M')+x(i)+','+y(p.n)).join(' ')}" fill="none" stroke="#24745e" stroke-width="2.5"/>`;
  points.forEach((p,i)=>{body+=`<circle cx="${x(i)}" cy="${y(p.n)}" r="3.2" fill="#24745e"><title>${p.month}：${number(p.n)} 单</title></circle>`;if(i%Math.ceil(points.length/6)===0||i===points.length-1)body+=`<text x="${x(i)}" y="257" text-anchor="middle">${p.month}</text>`;});
  $('#chart').innerHTML=svg(body,'按购买月份归属的已交付订单数；边界月份可能覆盖不全');$('#chart-note').textContent='按购买月份归属；没有订单记录的月份显示为 0，仅表示该数据集未观测到记录。边界和末期月份不可直接与完整月份比较。';
 }else if(name==='states'){
  $('#chart-title').textContent='地区延迟贡献';$('#chart-unit').textContent='延迟订单 / 单';const rows=r.states.slice(0,6),max=Math.max(...rows.map(x=>x.late_orders||0),1);rows.forEach((a,i)=>{const y=26+i*37,w=(a.late_orders||0)/max*470;body+=`<text x="43" y="${y+16}" text-anchor="end">${esc(a.state)}</text><rect x="58" y="${y}" width="${w}" height="23" rx="2" fill="#377f66"/><text x="${w+67}" y="${y+16}">${number(a.late_orders||0)} · ${percent(a.late_rate)}</text>`;});
  $('#chart').innerHTML=svg(body,'延迟订单数最多的六个客户地区，条形从零开始');$('#chart-note').textContent='按延迟订单数排序，图中最多显示六个地区。条形表示数量，旁注表示各组延迟率；下表提供所有地区、分母及贡献。';
 }else{
  $('#chart-title').textContent='交付体验与低评分';$('#chart-unit').textContent='低评分率 / %';const rows=['on_time','late'].map(k=>r.association.find(x=>x.delivery_group===k)).filter(Boolean);
  for(let i=0;i<=4;i++){const yy=232-i/4*195;body+=`<line x1="58" y1="${yy}" x2="690" y2="${yy}" stroke="#e2e8dd"/><text x="48" y="${yy+4}" text-anchor="end">${i*25}%</text>`;}
  rows.forEach((a,i)=>{const x=170+i*265,h=a.rate*195;body+=`<rect x="${x}" y="${232-h}" width="120" height="${h}" rx="2" fill="${i?'#275e4e':'#95b29a'}"/><text x="${x+60}" y="${220-h}" text-anchor="middle">${percent(a.rate)}</text><text x="${x+60}" y="254" text-anchor="middle">${a.delivery_group==='late'?'延迟交付':'按时交付'} · n=${number(a.n)}</text>`;});
  $('#chart').innerHTML=rows.length?svg(body,'有效履约及评分订单中的低评分率，纵轴零至百分之百'):'<p class="empty">缺少有效履约和评分订单，当前无法对比。</p>';const s=r.stratified;$('#chart-note').textContent=`仅含履约与评分都有效的已交付订单，低评分为 1–2 分。${s.orders?'月份 × 地区分层后的加权差异为 '+pp(s.weighted_difference)+'，覆盖 '+percent(s.coverage)+' 的交叉样本。':'共同分层样本不足。'}关联不能证明因果，未控制全部混杂。`;
 }
}
const chartTabs=$$('[data-chart]');chartTabs.forEach((b,i)=>{b.id='chart-tab-'+b.dataset.chart;b.setAttribute('aria-controls','chart');b.addEventListener('click',()=>renderChart(b.dataset.chart));b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%chartTabs.length;if(e.key==='ArrowLeft')n=(i+chartTabs.length-1)%chartTabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=chartTabs.length-1;if(n!==undefined){e.preventDefault();renderChart(chartTabs[n].dataset.chart);chartTabs[n].focus();}});});
const labels={total_orders:'订单主表订单数',delivered_orders:'已交付订单数',amount_cents:'已交付商品金额（分）',delivery_eligible:'履约有效分母',late_orders:'延迟订单数',review_eligible:'评价有效分母',low_reviews:'低评分订单数',all_item_cents:'全体商品明细金额（分）'};
function issueHTML(q){return q.summary.map(a=>`<div class="issue"><span class="badge ${a.severity==='error'?'status-error':'status-warn'}">${a.severity==='error'?'阻断':'警告'}</span><div><strong>${esc(a.message)}</strong><p>记录次数／受影响数量：${number(a.count)}（条目可能重叠，不能相加当作问题订单总数）</p><small>${esc(a.file)}${a.field?' / '+esc(a.field):''} · ${esc(a.code)}</small></div></div>`).join('')||'<p class="empty">未发现已定义规则内的问题，仍需核对源业务事实。</p>';}
function renderQuality(){const r=current,q=r.quality;$('#quality-overview').innerHTML=[['阻断项',number(q.errors),'当前快照无阻断才可切换'],['警告类型',number(q.summary.filter(x=>x.severity==='warning').length),'影响数量可能交叉，不作为可信度分数'],['独立复算',r.verification.status,r.verification.engines]].map(([a,b,c])=>`<div class="quality-tile"><span class="tiny-label">${a}</span><strong>${esc(b)}</strong><small>${esc(c)}</small></div>`).join('');$('#verification-table').innerHTML=r.verification.comparisons.map(a=>`<tr><td>${esc(labels[a.metric]||a.metric)}</td><td>${number(a.sql)}</td><td>${number(a.independent)}</td><td class="${a.passed?'status-pass':'status-error'}">${a.passed?'一致':'不一致'}</td></tr>`).join('');$('#python-status').textContent=r.verification.python?'公开案例额外验证：'+r.verification.python.engines+'，'+r.verification.python.aggregate_tables_verified+' 组聚合表一致。':'此版本已实时完成 SQL / JavaScript 双路径复算；尚未进行 Python 额外复算。';$('#quality-issues').innerHTML=issueHTML(q);$('#profiles').innerHTML=q.profiles.map(a=>`<div class="profile"><h3>${esc(a.file)} · 输入 ${number(a.input_rows)} 行 / 有效 ${number(a.accepted_rows)} 行</h3><p>${Object.entries(a.missing).filter(([,n])=>n).map(([k,n])=>esc(k)+' 缺失 '+number(n)+'（'+percent(a.input_rows?n/a.input_rows:null)+'）').join('；')||'已检查字段无空值'}</p></div>`).join('');}
$('#export-results').addEventListener('click',()=>download('olist-analysis-'+current.id+'.json',JSON.stringify(current,null,2)));
$('#export-quality').addEventListener('click',()=>download('olist-quality-'+current.id+'.json',JSON.stringify({id:current.id,quality:current.quality,verification:current.verification,file_hashes:current.file_hashes,code_sha256:current.code_sha256},null,2)));
$('#print-report').addEventListener('click',()=>{const previous=location.hash.slice(1)||'overview';panel('overview');window.addEventListener('afterprint',()=>panel(previous),{once:true});window.print();});
function progress(text,error=false){$('#import-progress').textContent=text;$('#import-progress').classList.remove('hidden');$('#import-progress').classList.toggle('error',error);}
function busy(on){$('#run-import').disabled=on;$('#cancel-import').classList.toggle('hidden',!on);$$('#import-form input').forEach(x=>x.disabled=on);}
$('#cancel-import').addEventListener('click',()=>{importRun++;worker?.terminate();worker=null;candidate=null;checkedQuality=null;busy(false);progress('检查已取消，当前版本保持不变。');$('#commit-import').classList.add('hidden');});
$('#import-form').addEventListener('change',()=>{candidate=null;checkedQuality=null;$('#commit-import').classList.add('hidden');$('#import-preview').classList.add('hidden');});
$('#import-form').addEventListener('submit',async e=>{e.preventDefault();const run=++importRun;candidate=null;checkedQuality=null;$('#import-preview').classList.add('hidden');$('#commit-import').classList.add('hidden');
 try{
  if(!database)throw Error('本机浏览器存储不可用，无法可靠保存和切换版本。请允许站点存储后重试。');
  if(location.protocol==='file:')throw Error('请使用云端网址或本地 HTTP 服务打开，文件路径模式不支持后台分析。');
  const selections={};let total=0;for(const name of ['orders','order_items','order_reviews']){const f=$('#file-'+name).files[0];if(!f)throw Error('请选择 '+name+'.csv');total+=f.size;selections[name+'.csv']=f;}if(total>80*1024*1024)throw Error('三份 CSV 合计最多 80 MB');const mf=$('#file-manifest').files[0];if(!mf||mf.size>100000)throw Error('请选择有效且小于 100 KB 的批次说明');
  busy(true);progress('读取文件，准备检查…');const files={};const decoder=new TextDecoder('utf-8',{fatal:true,ignoreBOM:true});for(const [name,f] of Object.entries(selections))files[name]=decoder.decode(await f.arrayBuffer());const manifest=JSON.parse(decoder.decode(await mf.arrayBuffer()).replace(/^\uFEFF/,''));
  if(run!==importRun)return;
  worker=new Worker('worker.js');worker.onmessage=event=>{if(run!==importRun)return;const data=event.data;if(data.type==='progress'){progress(data.message);return;}busy(false);worker?.terminate();worker=null;
   if(data.type==='error'){progress(data.message+'；当前版本保持不变。',true);return;}
   checkedQuality=data.quality||data.result.quality;$('#import-preview').classList.remove('hidden');
   if(data.type==='blocked'){progress('发现 '+number(checkedQuality.errors)+' 个阻断记录，当前版本保持不变。',true);$('#preview-content').innerHTML=issueHTML(checkedQuality);return;}
   candidate={id:data.result.id,result:data.result,files,manifest,saved_at:new Date().toISOString()};const r=data.result,m=r.metrics,sameBasis=current.manifest.source_uri_or_description===r.manifest.source_uri_or_description&&current.manifest.currency===r.manifest.currency&&current.manifest.source_timezone===r.manifest.source_timezone&&current.manifest.coverage_start===r.manifest.coverage_start&&current.manifest.coverage_end===r.manifest.coverage_end&&current.metric_version===r.metric_version;
   const sameInput=current.id===r.id;progress(sameInput?'相同批次已在使用；重复导入不会追加计数。':'检查和独立复算完成，尚未切换当前结果。');
   $('#preview-content').innerHTML=`<p><b>${esc(r.manifest.dataset_name)}</b> · ${esc(r.manifest.coverage_start)} 至 ${esc(r.manifest.coverage_end)}</p><div class="preview-metrics"><div>已交付订单<strong>${number(m.delivered_orders)}</strong></div><div>商品金额<strong>${esc(money(m.amount_cents,r.manifest.currency))}</strong></div><div>延迟率<strong>${percent(m.late_rate)}</strong></div><div>低评分占比<strong>${percent(m.low_rate)}</strong></div></div><p class="preview-details">结构检查：${r.quality.status}；独立复算：${r.verification.status}。版本 ${esc(r.id)}。${sameBasis?'同窗口、币种、时区与口径下，已交付订单差额为 '+number(m.delivered_orders-current.metrics.delivered_orders)+' 单；商品金额差额为 '+esc(money(m.amount_cents-current.metrics.amount_cents,r.manifest.currency))+'。':'与当前版本的窗口、币种、时区或口径不同，不直接计算业务增减。'}</p><p class="small">输入文件与识别字段</p>${r.quality.profiles.map(p=>`<p class="preview-details">${esc(p.file)}：${number(p.input_rows)} 行；${esc(Object.keys(p.missing).join(', '))}</p>`).join('')}${issueHTML(r.quality)}`;
   $('#commit-import').classList.toggle('hidden',sameInput);
  };worker.onerror=err=>{if(run!==importRun)return;worker?.terminate();worker=null;busy(false);progress('后台分析失败：'+err.message+'。当前版本保持不变。',true);};worker.postMessage({files,manifest});
 }catch(err){if(run!==importRun)return;busy(false);progress(err.message+'；当前版本保持不变。',true);}
});
$('#download-errors').addEventListener('click',()=>{if(!checkedQuality)return;download('import-checks.csv',Papa.unparse(checkedQuality.issues,{escapeFormulae:true}),'text/csv;charset=utf-8');});
$('#commit-import').addEventListener('click',async()=>{if(!candidate)return;const staged=candidate;$('#commit-import').disabled=true;try{await saveSnapshot(staged);current=staged.result;candidate=null;render();panel('overview');message('已切换到本机保存的完整快照。其他访客和公开案例不受影响。');}catch(err){progress('保存失败，保留上一有效版本。可能是浏览器存储配额不足：'+err.message,true);}finally{$('#commit-import').disabled=false;$('#commit-import').classList.add('hidden');}});
async function renderHistory(){if(!database){$('#history-list').innerHTML='<p class="empty">当前浏览器存储不可用，公开案例仍可查看。</p>';return;}try{const rows=(await getSnapshots()).sort((a,b)=>b.saved_at.localeCompare(a.saved_at));$('#history-list').innerHTML=rows.length?rows.map(a=>`<div class="history-item"><div><h3>${esc(a.manifest.dataset_name)} ${a.id===current.id?'· 当前':''}</h3><p>${esc(a.manifest.coverage_start)} 至 ${esc(a.manifest.coverage_end)} · ${number(a.result.metrics.delivered_orders)} 笔已交付订单</p><p>版本 ${esc(a.id)} · 保存于 ${esc(new Date(a.saved_at).toLocaleString('zh-CN'))}</p></div><div class="history-actions"><button class="button ghost" data-restore="${esc(a.id)}">恢复此版本</button><button class="button ghost" data-batch="${esc(a.id)}">导出完整批次 ↓</button></div></div>`).join(''):'<p class="empty">还没有本机导入版本。公开案例可随时恢复。</p>';$$('[data-restore]').forEach(b=>b.onclick=async()=>{try{const a=await getValue('snapshots',b.dataset.restore);if(!a)throw Error('该版本不存在');await saveSnapshot(a);current=a.result;render();renderHistory();message('已恢复所选完整快照。');}catch(err){message('恢复失败，当前版本未改变：'+err.message,true);}});$$('[data-batch]').forEach(b=>b.onclick=async()=>{const a=await getValue('snapshots',b.dataset.batch);if(a)download('olist-batch-'+a.id+'.json',JSON.stringify({manifest:a.manifest,files:a.files,result:a.result}));});}catch(err){message('无法读取版本记录：'+err.message,true);}}
$('#restore-case').addEventListener('click',async()=>{try{if(database)await saveSnapshot(null);current=window.OLIST_CASE;render();renderHistory();message('已恢复公开 Kaggle 案例，本机导入版本仍保留。');}catch(err){message('恢复失败：'+err.message,true);}});
$('#backup-file').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>110*1024*1024)throw Error('备份文件最多 110 MB');const data=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer()));if(!data.files||!data.manifest)throw Error('缺少 files 或 manifest，无法作为完整批次恢复');for(const key of ['orders','order_items','order_reviews']){const name=key+'.csv';if(typeof data.files[name]!=='string')throw Error('备份缺少 '+name);const dt=new DataTransfer();dt.items.add(new File([data.files[name]],name,{type:'text/csv'}));$('#file-'+key).files=dt.files;}const dt=new DataTransfer();dt.items.add(new File([JSON.stringify(data.manifest)],'dataset_manifest.json',{type:'application/json'}));$('#file-manifest').files=dt.files;candidate=null;checkedQuality=null;panel('import');$('#import-form').requestSubmit();}catch(err){message('备份恢复失败，当前版本未改变：'+err.message,true);}finally{e.target.value='';}});
(async()=>{render();panel(location.hash.slice(1));try{database=await openDB();const id=await getValue('settings','current');if(id){const saved=await getValue('snapshots',id);if(saved){current=saved.result;render();}}if(location.hash==='#history')renderHistory();}catch(err){message('浏览器存储不可用：仍可查看公开案例，导入与版本保存暂不可用。',true);}})();
